-- E-08 custom cake requests and quotes (S-151, S-153, S-155; FR-028, FR-029). Additive and
-- forward-only. Numbered 0016: 0013..0015 are reserved for promotions follow-ups, Juice payment,
-- accounts/reviews and order management, built in parallel.
--
-- 1. storage_purge.due_at (generated by drizzle-kit, snapshot 0016): a customer's request photo
--    is queued for removal when its signed upload URL is issued, due 24 h later; the submit below
--    drops the queue row of every photo an order takes, so the purgeStorage job removes only
--    uploads that were never attached (S-153 AC7). Existing rows keep due_at = now() (due at once).
-- 2. submit_custom_request: the whole request write in one CALL (one round trip, one
--    transaction; ADR-0003 amendment 3), like place_order. The application has already parsed the
--    form, checked the date against fresh Settings, verified each photo object in Storage (type by
--    magic number, size) and resolved the time window; this procedure decides only what needs the
--    database: the idempotency replay, that every photo path was issued by requestUploadUrls and is
--    not attached yet (its queue row), the gallery photo, and the checked write.
--
-- 3. orders.awaiting_payment_since (generated): an accepted quote enters the Juice payment flow
--    (awaiting_payment, S-158) days after the request was created; its 24 h deadline and 12 h
--    reminder count from this instant instead of created_at (website orders keep it NULL).
--
-- Rollback: a later migration drops the procedure (requests in flight are rows, unaffected) and
-- the column (the purge job then removes queued rows at once, as before 0016).
ALTER TABLE "orders" ADD COLUMN "awaiting_payment_since" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "storage_purge" ADD COLUMN "due_at" timestamp with time zone DEFAULT now() NOT NULL;--> statement-breakpoint
CREATE INDEX "storage_purge_due_idx" ON "storage_purge" USING btree ("due_at");
--> statement-breakpoint
CREATE PROCEDURE "public"."submit_custom_request"(p_input jsonb, INOUT result jsonb)
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_key uuid := nullif(p_input->>'idempotencyKey', '')::uuid;
  v_order jsonb := p_input->'order';
  v_request jsonb := p_input->'request';
  v_photos jsonb := coalesce(p_input->'photos', '[]'::jsonb);
  v_bucket text := p_input->>'bucket';
  v_existing jsonb;
  v_customer uuid;
  v_number integer;
  v_order_id uuid;
  v_paths text[];
  v_issued integer;
  v_constraint text;
  v_prefix text;
BEGIN
  SELECT s.order_number_prefix INTO v_prefix FROM settings s WHERE s.id = 1;
  -- Step 1: a known key returns the order it created (double tap, retry after a network drop).
  IF v_key IS NOT NULL THEN
    SELECT jsonb_build_object('orderId', o.id, 'number', o.number, 'trackingToken', o.tracking_token, 'locale', o.locale,
        'contactEmail', o.contact_email, 'orderNumberPrefix', coalesce(o.number_prefix, v_prefix))
      INTO v_existing FROM orders o WHERE o.idempotency_key = v_key;
    IF v_existing IS NOT NULL THEN
      result := jsonb_build_object('kind', 'existing', 'existing', v_existing);
      RETURN;
    END IF;
  END IF;

  -- Step 2: every uploaded photo must still be queued (issued by requestUploadUrls, not yet
  -- attached to an order, not yet purged). The gallery photo must exist (it is referenced).
  SELECT coalesce(array_agg(p.value->>'path'), '{}') INTO v_paths
    FROM jsonb_array_elements(v_photos) p WHERE p.value->>'path' IS NOT NULL;
  SELECT count(*) INTO v_issued FROM storage_purge q WHERE q.bucket = v_bucket AND q.path = ANY (v_paths);
  IF v_issued <> cardinality(v_paths) OR cardinality(v_paths) <> (SELECT count(DISTINCT x) FROM unnest(v_paths) x)
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_photos) p
                WHERE p.value->>'galleryPhotoId' IS NOT NULL
                  AND NOT EXISTS (SELECT 1 FROM gallery_photo g WHERE g.id = (p.value->>'galleryPhotoId')::uuid)) THEN
    result := jsonb_build_object('kind', 'rejected');
    RETURN;
  END IF;

  BEGIN
    SELECT c.id INTO v_customer FROM customer c WHERE lower(c.email) = lower(v_order->>'contactEmail') LIMIT 1;
    IF v_customer IS NULL THEN
      INSERT INTO customer (name, phone, email, locale)
        VALUES (v_order->>'contactName', v_order->>'contactPhone', lower(v_order->>'contactEmail'), (v_order->>'locale')::locale)
        ON CONFLICT DO NOTHING
        RETURNING id INTO v_customer;
      IF v_customer IS NULL THEN
        SELECT c.id INTO v_customer FROM customer c WHERE lower(c.email) = lower(v_order->>'contactEmail') LIMIT 1;
      END IF;
      IF v_customer IS NULL THEN
        RAISE EXCEPTION 'customer insert conflicted but no row matches the email';
      END IF;
    END IF;

    UPDATE counter SET value = value + 1 WHERE name = 'order_number' RETURNING value INTO v_number;
    IF v_number IS NULL THEN
      RAISE EXCEPTION 'counter ''order_number'' is missing (run the migrations)';
    END IF;

    -- No price yet: the quote sets total_rs (FR-030); delivery is part of the quoted total.
    INSERT INTO orders (
      number, source, status, customer_id, contact_name, contact_phone, contact_email, fulfilment, address, landmark,
      fulfil_on, time_window, items_total_rs, delivery_fee_rs, total_rs, locale, tracking_token, idempotency_key, policies_accepted_at
    ) VALUES (
      v_number, 'custom_request', 'quote_needed', v_customer, v_order->>'contactName', v_order->>'contactPhone', v_order->>'contactEmail',
      (v_order->>'fulfilment')::fulfilment, v_order->>'address', v_order->>'landmark',
      (v_order->>'fulfilOn')::date, v_order->'window', 0, 0, 0,
      (v_order->>'locale')::locale, v_order->>'trackingToken', v_key, (v_order->>'policiesAcceptedAt')::timestamptz
    ) RETURNING id INTO v_order_id;

    INSERT INTO custom_request (order_id, occasion, servings, flavours, theme, cake_text, budget_rs, details)
      VALUES (v_order_id, v_request->>'occasion', (v_request->>'servings')::smallint, v_request->>'flavours', v_request->>'theme',
              v_request->>'cakeText', (v_request->>'budgetRs')::integer, v_request->>'details');

    -- Photos in the customer's order, slots 0..4 (the table's check and unique slot cap at 5).
    INSERT INTO custom_request_photo (order_id, storage_path, sort_order, source_gallery_photo_id)
      SELECT v_order_id, coalesce(p.value->>'path', g.storage_path), (p.ordinality - 1)::smallint, g.id
        FROM jsonb_array_elements(v_photos) WITH ORDINALITY AS p(value, ordinality)
        LEFT JOIN gallery_photo g ON g.id = (p.value->>'galleryPhotoId')::uuid;

    -- Attached: never purged (S-153 AC7).
    DELETE FROM storage_purge q WHERE q.bucket = v_bucket AND q.path = ANY (v_paths);

    INSERT INTO order_event (order_id, actor_type, type, to_status, details)
      VALUES (v_order_id, 'customer', 'created', 'quote_needed', jsonb_build_object('photoCount', jsonb_array_length(v_photos)));

    INSERT INTO email_outbox (template, to_email, locale, payload, order_id, dedupe_key)
      VALUES ('request_received', v_order->>'contactEmail', (v_order->>'locale')::locale, jsonb_build_object('orderId', v_order_id),
              v_order_id, 'order:' || v_order_id || ':request_received');

    -- Admin email alert (FR-072 "New custom request"): active admins with email alerts on, in
    -- their language. Push alerts arrive with E-10.
    INSERT INTO email_outbox (template, to_email, locale, payload, order_id, dedupe_key)
      SELECT 'admin_alert_new_request', a.email, a.locale, jsonb_build_object('orderId', v_order_id), v_order_id,
             'order:' || v_order_id || ':admin_alert:new_request:' || a.id
        FROM admin a WHERE a.active AND a.alert_email;
  EXCEPTION WHEN unique_violation THEN
    -- Lost race on the key: both calls passed the lookup; ours is rolled back (no number consumed).
    GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
    IF v_constraint IS DISTINCT FROM 'orders_idempotency_key_unique' THEN
      RAISE;
    END IF;
    SELECT jsonb_build_object('orderId', o.id, 'number', o.number, 'trackingToken', o.tracking_token, 'locale', o.locale,
        'contactEmail', o.contact_email, 'orderNumberPrefix', coalesce(o.number_prefix, v_prefix))
      INTO v_existing FROM orders o WHERE o.idempotency_key = v_key;
    result := jsonb_build_object('kind', 'existing', 'existing', v_existing);
    RETURN;
  END;

  result := jsonb_build_object('kind', 'placed', 'placed', jsonb_build_object('orderId', v_order_id, 'number', v_number,
    'trackingToken', v_order->>'trackingToken', 'locale', v_order->>'locale', 'orderNumberPrefix', v_prefix));
END;
$$;
